const MAX_ARCHIVE_BYTES=16*1024*1024,MAX_UNPACKED_BYTES=64*1024*1024;

function sha256(value){return crypto.createHash('sha256').update(value).digest('hex')}
function safePath(value){const path=String(value||'').replaceAll('\\','/');if(!path||path.startsWith('/')||path.split('/').some(part=>!part||part==='.'||part==='..'))throw Object.assign(new Error('Releasepfad ist unsicher.'),{code:'RELEASE_PATH_INVALID'});if(Buffer.byteLength(path)>100)throw Object.assign(new Error('Releasepfad überschreitet das portable Tar-Limit.'),{code:'RELEASE_PATH_TOO_LONG'});return path}
