function writeText(buffer,offset,length,value){Buffer.from(String(value)).copy(buffer,offset,0,length)}
function tarHeader({path,size,mode=0o644,mtime=0}){const header=Buffer.alloc(512);writeText(header,0,100,safePath(path));writeText(header,100,8,octal(mode,8));writeText(header,108,8,octal(0,8));writeText(header,116,8,octal(0,8));writeText(header,124,12,octal(size,12));writeText(header,136,12,octal(mtime,12));header.fill(0x20,148,156);header[156]=0x30;writeText(header,257,6,'ustar\0');writeText(header,263,2,'00');writeText(header,265,32,'root');writeText(header,297,32,'root');const checksum=header.reduce((sum,byte)=>sum+byte,0);writeText(header,148,8,`${checksum.toString(8).padStart(6,'0')}\0 `);return header}
function createTar(entries,{mtime=0}={}){const chunks=[];for(const entry of [...entries].sort((a,b)=>a.path.localeCompare(b.path,'en'))){const content=Buffer.isBuffer(entry.content)?entry.content:Buffer.from(entry.content);chunks.push(tarHeader({path:entry.path,size:content.length,mode:entry.mode,mtime}),content);const padding=(512-content.length%512)%512;if(padding)chunks.push(Buffer.alloc(padding))}chunks.push(Buffer.alloc(1024));return Buffer.concat(chunks)}
function createManifest(entries,{name,version,target='systemone-pi',sourceCommit,sourceTimestamp}){if(!/^[a-f0-9]{40}$/.test(String(sourceCommit||'')))throw Object.assign(new Error('Vollständiger Git-Commit fehlt.'),{code:'RELEASE_COMMIT_INVALID'});const files=[...entries].map(entry=>{const content=Buffer.isBuffer(entry.content)?entry.content:Buffer.from(entry.content);return{path:safePath(entry.path),size:content.length,mode:entry.mode===0o755?'0755':'0644',sha256:sha256(content)}}).sort((a,b)=>a.path.localeCompare(b.path,'en'));return{schemaVersion:1,format:'systemone-release-bundle',name,version,target,sourceCommit,sourceTimestamp:new Date(Number(sourceTimestamp)*1000).toISOString(),files}}
function createReleaseBundle(entries,metadata){const manifest=createManifest(entries,metadata),manifestBytes=Buffer.from(`${JSON.stringify(manifest,null,2)}\n`),archiveEntries=[...entries,{path:'RELEASE-MANIFEST.json',content:manifestBytes,mode:0o644}],tar=createTar(archiveEntries,{mtime:Number(metadata.sourceTimestamp)}),archive=zlib.gzipSync(tar,{level:9,mtime:0});return{archive,archiveSha256:sha256(archive),manifest}}
function verifyReleaseManifest(root,manifest){if(manifest?.schemaVersion!==1||manifest?.format!=='systemone-release-bundle'||manifest?.target!=='systemone-pi'||!/^[a-f0-9]{40}$/.test(String(manifest?.sourceCommit||''))||!Array.isArray(manifest?.files))throw Object.assign(new Error('Release-Manifest ist ungültig.'),{code:'RELEASE_MANIFEST_INVALID'});const seen=new Set();for(const file of manifest.files){const relative=safePath(file.path);if(seen.has(relative))throw Object.assign(new Error(`Doppelter Releasepfad: ${relative}`),{code:'RELEASE_FILE_DUPLICATE'});seen.add(relative);const absolute=path.join(root,relative),stat=fs.lstatSync(absolute);if(!stat.isFile()||stat.isSymbolicLink())throw Object.assign(new Error(`Releaseeintrag ist keine reguläre Datei: ${relative}`),{code:'RELEASE_FILE_INVALID'});const content=fs.readFileSync(absolute),mode=(stat.mode&0o111)?'0755':'0644';if(content.length!==file.size||sha256(content)!==file.sha256||mode!==file.mode)throw Object.assign(new Error(`Release-Datei weicht vom Manifest ab: ${relative}`),{code:'RELEASE_FILE_TAMPERED'})}return true}
function tarString(buffer,start,length){const end=buffer.indexOf(0,start);return buffer.subarray(start,end<0||end>start+length?start+length:end).toString('utf8')}
function tarNumber(buffer,start,length){const value=tarString(buffer,start,length).trim();if(!/^[0-7]+$/.test(value))throw Object.assign(new Error('Tar-Zahlenfeld ist ungültig.'),{code:'RELEASE_ARCHIVE_INVALID'});return Number.parseInt(value,8)}
function inspectReleaseBundleArchive(archive){if(!Buffer.isBuffer(archive)||archive.length===0||archive.length>MAX_ARCHIVE_BYTES)throw Object.assign(new Error('Release-Archiv fehlt oder überschreitet das Größenlimit.'),{code:'RELEASE_ARCHIVE_SIZE'});let tar;try{tar=zlib.gunzipSync(archive,{maxOutputLength:MAX_UNPACKED_BYTES})}catch{throw Object.assign(new Error('Release-Archiv ist kein gültiges begrenztes Gzip-Archiv.'),{code:'RELEASE_ARCHIVE_INVALID'})}const entries=new Map();let offset=0,zeroBlocks=0;while(offset+512<=tar.length){const header=tar.subarray(offset,offset+512);offset+=512;if(header.every(byte=>byte===0)){zeroBlocks++;if(zeroBlocks===2)break;continue}zeroBlocks=0;const expected=tarNumber(header,148,8),copy=Buffer.from(header);copy.fill(0x20,148,156);const actual=copy.reduce((sum,byte)=>sum+byte,0);if(expected!==actual)throw Object.assign(new Error('Tar-Header-Prüfsumme ist ungültig.'),{code:'RELEASE_ARCHIVE_INVALID'});const relative=safePath(tarString(header,0,100)),type=String.fromCharCode(header[156]||0x30);if(type!=='0'&&type!=='\0')throw Object.assign(new Error(`Nicht regulärer Archiveintrag: ${relative}`),{code:'RELEASE_ARCHIVE_ENTRY_INVALID'});const size=tarNumber(header,124,12),mode=(tarNumber(header,100,8)&0o111)?'0755':'0644';if(size>MAX_UNPACKED_BYTES||offset+size>tar.length)throw Object.assign(new Error('Archiveintrag überschreitet Grenzen.'),{code:'RELEASE_ARCHIVE_INVALID'});if(entries.has(relative))throw Object.assign(new Error(`Doppelter Archiveintrag: ${relative}`),{code:'RELEASE_FILE_DUPLICATE'});entries.set(relative,{content:tar.subarray(offset,offset+size),mode});offset+=Math.ceil(size/512)*512}if(zeroBlocks<2||offset>tar.length||tar.subarray(offset).some(byte=>byte!==0))throw Object.assign(new Error('Tar-Abschluss fehlt, enthält Folgedaten oder ist ungültig.'),{code:'RELEASE_ARCHIVE_INVALID'});const manifestEntry=entries.get('RELEASE-MANIFEST.json');if(!manifestEntry)throw Object.assign(new Error('Eingebettetes Release-Manifest fehlt.'),{code:'RELEASE_MANIFEST_MISSING'});if(manifestEntry.mode!=='0644')throw Object.assign(new Error('Eingebettetes Release-Manifest besitzt einen unsicheren Modus.'),{code:'RELEASE_MANIFEST_INVALID'});let manifest;try{manifest=JSON.parse(manifestEntry.content.toString('utf8'))}catch{throw Object.assign(new Error('Eingebettetes Release-Manifest ist kein JSON.'),{code:'RELEASE_MANIFEST_INVALID'})}if(manifest?.schemaVersion!==1||manifest?.format!=='systemone-release-bundle'||manifest?.target!=='systemone-pi'||!/^[a-f0-9]{40}$/.test(String(manifest?.sourceCommit||''))||!Array.isArray(manifest?.files))throw Object.assign(new Error('Eingebettetes Release-Manifest ist ungültig.'),{code:'RELEASE_MANIFEST_INVALID'});if(entries.size!==manifest.files.length+1)throw Object.assign(new Error('Archivinhalt stimmt nicht vollständig mit dem Manifest überein.'),{code:'RELEASE_ARCHIVE_CONTENT_MISMATCH'});const seen=new Set();for(const file of manifest.files){const relative=safePath(file.path),entry=entries.get(relative);if(seen.has(relative)||!entry||entry.content.length!==file.size||entry.mode!==file.mode||sha256(entry.content)!==file.sha256)throw Object.assign(new Error(`Archiveintrag weicht vom Manifest ab: ${relative}`),{code:'RELEASE_ARCHIVE_CONTENT_MISMATCH'});seen.add(relative)}return{valid:true,manifest,fileCount:manifest.files.length,unpackedBytes:tar.length}}

module.exports={MAX_ARCHIVE_BYTES,MAX_UNPACKED_BYTES,sha256,safePath,createTar,createManifest,createReleaseBundle,verifyReleaseManifest,inspectReleaseBundleArchive};
